5	namespace App\Ordering\Domain\Model;
6	
7	use App\Ordering\Domain\Event\OrderCancelled;
8	use App\Ordering\Domain\Event\OrderConfirmed;
9	use App\Ordering\Domain\Event\OrderDelivered;
10	use App\Ordering\Domain\Event\OrderItemAdded;
11	use App\Ordering\Domain\Event\OrderPaid;
12	use App\Ordering\Domain\Event\OrderPlaced;
13	use App\Ordering\Domain\Event\OrderShipped;
14	use App\Ordering\Domain\Exception\CurrencyMismatchException;
15	use App\Ordering\Domain\Exception\EmptyOrderException;
16	use App\Ordering\Domain\Exception\InvalidOrderStateTransitionException;
17	use App\Ordering\Domain\ValueObject\CustomerId;
18	use App\Ordering\Domain\ValueObject\OrderId;
19	use App\Ordering\Domain\ValueObject\OrderStatus;
20	use App\Ordering\Domain\ValueObject\ProductId;
21	use App\SharedKernel\Domain\AggregateRoot;
22	use App\SharedKernel\Domain\Currency;
