14	#[ORM\Entity]
15	#[ORM\Table(name: 'stock_items')]
16	final class StockItem extends AggregateRoot
17	{
18	    /**
19	     * Rezervace podle objednávky: ID objednávky => počet kusů.
20	     */
21	    #[ORM\Column(type: 'json')]
22	    private array $reservations = [];
23	
24	    public function __construct(
25	        #[ORM\Id]
26	        #[ORM\Column(type: 'product_id')]
27	        public readonly ProductId $productId,
28	        #[ORM\Column]
29	        public private(set) int $onHand,
30	    ) {
31	        if ($onHand < 0) {
32	            throw new \InvalidArgumentException('Stock on hand cannot be negative');
33	        }
34	    }
35	
36	    /** Kusy, které jde ještě rezervovat. */
37	    public function available(): int
38	    {
39	        return $this->onHand - $this->reserved();
40	    }
41	
42	    public function reserved(): int
43	    {
44	        return array_sum($this->reservations);
45	    }
46	
47	    public function reserve(OrderId $orderId, int $quantity): void
48	    {
49	        if ($quantity < 1) {
50	            throw new \InvalidArgumentException('Reserved quantity must be positive');
51	        }
52	
53	        // INVARIANT: rezervace nepřesáhne zásobu.
54	        if ($quantity > $this->available()) {
55	            throw InsufficientStockException::forProduct($this->productId, $quantity, $this->available());
56	        }
57	
58	        $this->reservations[$orderId->value] = ($this->reservations[$orderId->value] ?? 0) + $quantity;
59	    }
60	
61	    public function release(OrderId $orderId): void
62	    {
63	        // INVARIANT: uvolnit jde jen to, co je rezervované.
64	        if (!$this->hasReservationFor($orderId)) {
65	            throw NothingReservedException::forOrder($this->productId, $orderId);
66	        }
67	
68	        unset($this->reservations[$orderId->value]);
69	    }
70	
71	    public function hasReservationFor(OrderId $orderId): bool
72	    {
73	        return isset($this->reservations[$orderId->value]);
74	    }
75	
76	    /** Rezervace jako pole pro přehledy a repozitář. */
77	    public function reservations(): array
78	    {
79	        return $this->reservations;
80	    }
81	
82	    /** Naskladnění od dodavatele. */
83	    public function receive(int $quantity): void
84	    {
85	        if ($quantity < 1) {
86	            throw new \InvalidArgumentException('Received quantity must be positive');
87	        }
88	
89	        $this->onHand += $quantity;
90	    }
91	}
