26	#[CoversClass(Order::class)]
27	final class OrderTest extends TestCase
28	{
29	    #[Test]
30	    public function placedOrderIsDraftAndRecordsOrderPlaced(): void
31	    {
32	        $order = Order::place(OrderId::generate(), CustomerId::generate());
33	
34	        self::assertSame(OrderStatus::Draft, $order->status);
35	        $events = $order->releaseEvents();
36	        self::assertCount(1, $events);
37	        self::assertInstanceOf(OrderPlaced::class, $events[0]);
38	    }
39	
40	    #[Test]
41	    public function sameProductIsAddedToExistingItem(): void
42	    {
43	        $order = $this->draftOrder();
44	        $order->releaseEvents();
45	        $productId = ProductId::generate();
46	
47	        $order->addItem($productId, 1, $this->czk(500_00));
48	        $order->addItem($productId, 2, $this->czk(500_00));
49	
50	        self::assertCount(1, $order->items);
51	        self::assertSame(3, $order->items[0]->quantity);
52	        self::assertContainsOnlyInstancesOf(OrderItemAdded::class, $order->releaseEvents());
53	    }
54	
55	    #[Test]
56	    public function itemCannotBeAddedToConfirmedOrder(): void
57	    {
58	        $order = $this->confirmedOrder();
59	
60	        $this->expectException(InvalidOrderStateTransitionException::class);
61	        $order->addItem(ProductId::generate(), 1, $this->czk(100_00));
62	    }
63	
64	    #[Test]
65	    public function itemInOtherCurrencyIsRejected(): void
66	    {
67	        $order = $this->draftOrder();
68	
69	        $this->expectException(CurrencyMismatchException::class);
70	        $order->addItem(ProductId::generate(), 1, new Money(100_00, Currency::EUR));
71	    }
72	
73	    #[Test]
74	    public function emptyOrderCannotBeConfirmed(): void
75	    {
76	        $order = $this->draftOrder();
77	
78	        $this->expectException(EmptyOrderException::class);
79	        $order->confirm();
80	    }
81	
82	    #[Test]
83	    public function confirmedOrderRecordsOrderConfirmed(): void
84	    {
85	        $order = $this->draftOrder();
86	        $order->addItem(ProductId::generate(), 1, $this->czk(100_00));
87	        $order->releaseEvents();
88	
89	        $order->confirm(new \DateTimeImmutable('2026-03-10 10:00'));
90	
91	        self::assertSame(OrderStatus::Confirmed, $order->status);
92	        self::assertEquals(new \DateTimeImmutable('2026-03-10 10:00'), $order->placedAt);
93	        $events = $order->releaseEvents();
94	        self::assertCount(1, $events);
95	        self::assertInstanceOf(OrderConfirmed::class, $events[0]);
96	    }
97	
98	    #[Test]
99	    public function draftOrderCannotBePaid(): void
100	    {
101	        $order = $this->draftOrder();
102	
103	        $this->expectException(InvalidOrderStateTransitionException::class);
104	        $order->markPaid();
105	    }
106	
107	    #[Test]
108	    public function secondPaymentRecordsNothing(): void
109	    {
110	        $order = $this->paidOrder();
111	        $order->releaseEvents();
112	
113	        $order->markPaid();
114	
115	        self::assertSame(OrderStatus::Paid, $order->status);
116	        self::assertSame([], $order->releaseEvents());
117	    }
118	
119	    #[Test]
120	    public function paidOrderRecordsOrderPaid(): void
121	    {
122	        $order = $this->confirmedOrder();
123	        $order->releaseEvents();
124	
125	        $order->markPaid();
126	
127	        $events = $order->releaseEvents();
128	        self::assertCount(1, $events);
129	        self::assertInstanceOf(OrderPaid::class, $events[0]);
130	    }
131	
132	    #[Test]
133	    public function confirmedOrderCannotBeShipped(): void
134	    {
135	        $order = $this->confirmedOrder();
136	
137	        $this->expectException(InvalidOrderStateTransitionException::class);
138	        $order->ship();
139	    }
140	
141	    #[Test]
142	    public function shippedOrderCanBeDelivered(): void
143	    {
144	        $order = $this->shippedOrder();
145	
146	        $order->deliver();
147	
148	        self::assertSame(OrderStatus::Delivered, $order->status);
149	    }
150	
151	    #[Test]
152	    public function paidOrderCanBeCancelled(): void
153	    {
154	        $order = $this->paidOrder();
155	        $order->releaseEvents();
156	
157	        $order->cancel('customer request', new \DateTimeImmutable());
158	
159	        self::assertSame(OrderStatus::Cancelled, $order->status);
160	        $events = $order->releaseEvents();
161	        self::assertCount(1, $events);
162	        self::assertInstanceOf(OrderCancelled::class, $events[0]);
163	    }
164	
165	    #[Test]
166	    public function draftOrderCanBeCancelled(): void
167	    {
168	        $order = $this->draftOrder();
169	
170	        $order->cancel('customer request', new \DateTimeImmutable());
171	
172	        self::assertSame(OrderStatus::Cancelled, $order->status);
173	    }
