175	    #[Test]
176	    public function shippedOrderCannotBeCancelled(): void
177	    {
178	        $order = $this->shippedOrder();
179	        $order->releaseEvents();
180	
181	        try {
182	            $order->cancel('customer request', new \DateTimeImmutable());
