194	        $order->cancel('customer request', new \DateTimeImmutable());
195	        $order->releaseEvents();
196	
197	        $order->cancel('customer request', new \DateTimeImmutable());
198	
199	        self::assertSame(OrderStatus::Cancelled, $order->status);
200	        self::assertSame([], $order->releaseEvents());
201	    }
