225	    #[Test]
226	    public function orderIsOwnedByCustomerWhoPlacedIt(): void
227	    {
228	        $customerId = CustomerId::generate();
229	        $order = Order::place(OrderId::generate(), $customerId);
230	
231	        self::assertTrue($order->isOwnedBy($customerId));
232	        self::assertFalse($order->isOwnedBy(CustomerId::generate()));
233	    }
