235	    private function draftOrder(): Order
236	    {
237	        return Order::place(OrderId::generate(), CustomerId::generate());
238	    }
239	
240	    private function confirmedOrder(): Order
241	    {
242	        $order = $this->draftOrder();
243	        $order->addItem(ProductId::generate(), 2, $this->czk(500_00));
