245	
246	        return $order;
247	    }
248	
249	    private function paidOrder(): Order
250	    {
251	        $order = $this->confirmedOrder();
252	        $order->markPaid();
253	
254	        return $order;
255	    }
256	
257	    private function shippedOrder(): Order
258	    {
259	        $order = $this->paidOrder();
260	        $order->ship();
261	
262	        return $order;
263	    }
264	
